/* Every Publish kept as a release that never changes: `site_releases`, one row per publish of a website (its creator, its install, when, and a manifest of the live theme settings, every page's live sections and every live theme file by path with the sha256 of its text), `theme_file_blobs`, each file's text kept once by its sha256 however many releases and websites share it, and `site_live_releases`, which release a website is drawn from now. A trigger `site_live_release_forget` on `store_theme_custom_files`, `store_theme_settings` and `store_theme_pages` lets go of that pointer whenever a live file, setting or page changes any other way than a publish (a file deleted or renamed in the code editor, a live setting saved), so the website is then drawn from its rows exactly as before until the next Publish. Draft saves do not touch it. Server only: row level security on, nothing for visitors or signed in users. Changes no existing row. Needs the theme tables (RUN_CREATOR_PAGE_AND_SITES); without them it skips itself with a notice. Until it runs, Publish and the live website work exactly as before. Safe to run again. */
CREATE TABLE IF NOT EXISTS public.theme_file_blobs (sha256 text PRIMARY KEY CHECK (sha256 ~ '^[0-9a-f]{64}$'), content text NOT NULL, size integer NOT NULL DEFAULT 0 CHECK (size >= 0), created_at timestamptz NOT NULL DEFAULT now());
ALTER TABLE public.theme_file_blobs ENABLE ROW LEVEL SECURITY;
REVOKE ALL ON public.theme_file_blobs FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.store_theme_installs') IS NULL THEN RAISE NOTICE 'part 180: store_theme_installs is missing, site_releases is skipped. Run the theme tables first, then this part again.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.site_releases (id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid NOT NULL, install_id uuid NOT NULL REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, created_at timestamptz NOT NULL DEFAULT now(), manifest jsonb NOT NULL CHECK (jsonb_typeof(manifest) = 'object'), file_count integer NOT NULL DEFAULT 0 CHECK (file_count >= 0), total_bytes bigint NOT NULL DEFAULT 0 CHECK (total_bytes >= 0)); CREATE INDEX IF NOT EXISTS idx_site_releases_install_created ON public.site_releases (install_id, created_at DESC); ALTER TABLE public.site_releases ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.site_releases FROM PUBLIC, anon, authenticated; END $do$;
DO $do$ BEGIN IF to_regclass('public.site_releases') IS NULL THEN RAISE NOTICE 'part 180: site_releases is missing, site_live_releases is skipped.'; RETURN; END IF; CREATE TABLE IF NOT EXISTS public.site_live_releases (install_id uuid PRIMARY KEY REFERENCES public.store_theme_installs(id) ON DELETE CASCADE, creator_id uuid NOT NULL, release_id uuid REFERENCES public.site_releases(id) ON DELETE SET NULL, rev bigint NOT NULL DEFAULT 0, updated_at timestamptz NOT NULL DEFAULT now()); CREATE INDEX IF NOT EXISTS idx_site_live_releases_creator ON public.site_live_releases (creator_id); ALTER TABLE public.site_live_releases ENABLE ROW LEVEL SECURITY; REVOKE ALL ON public.site_live_releases FROM PUBLIC, anon, authenticated; END $do$;
CREATE OR REPLACE FUNCTION public.site_live_release_forget() RETURNS trigger LANGUAGE plpgsql SECURITY DEFINER SET search_path = public, pg_temp AS $f$ DECLARE v_old uuid; v_new uuid; v_flag text; BEGIN IF to_regclass('public.site_live_releases') IS NULL THEN RETURN NULL; END IF; IF TG_OP <> 'INSERT' THEN v_old := OLD.install_id; END IF; IF TG_OP <> 'DELETE' THEN v_new := NEW.install_id; END IF; IF TG_ARGV[0] = 'file' THEN IF TG_OP = 'INSERT' AND coalesce(NEW.content, '') = '' THEN RETURN NULL; END IF; IF TG_OP = 'DELETE' AND coalesce(OLD.content, '') = '' THEN RETURN NULL; END IF; IF TG_OP = 'UPDATE' AND NEW.content IS NOT DISTINCT FROM OLD.content AND NEW.path IS NOT DISTINCT FROM OLD.path AND v_old = v_new THEN RETURN NULL; END IF; ELSIF TG_ARGV[0] = 'settings' THEN IF TG_OP = 'UPDATE' AND NEW.settings IS NOT DISTINCT FROM OLD.settings AND v_old = v_new THEN RETURN NULL; END IF; ELSIF TG_ARGV[0] = 'page' THEN IF TG_OP = 'UPDATE' AND NEW.sections IS NOT DISTINCT FROM OLD.sections AND NEW.page_key IS NOT DISTINCT FROM OLD.page_key AND v_old = v_new THEN RETURN NULL; END IF; END IF; IF v_old IS NULL OR v_new IS NULL OR v_old = v_new THEN v_flag := coalesce(current_setting('storelib.release_forgot', true), ''); IF position(coalesce(v_new, v_old)::text IN v_flag) > 0 THEN RETURN NULL; END IF; PERFORM set_config('storelib.release_forgot', v_flag || ',' || coalesce(v_new, v_old)::text, true); END IF; UPDATE public.site_live_releases SET release_id = NULL, rev = rev + 1, updated_at = now() WHERE install_id = v_old OR install_id = v_new; RETURN NULL; END $f$;
REVOKE ALL ON FUNCTION public.site_live_release_forget() FROM PUBLIC, anon, authenticated;
DO $do$ BEGIN IF to_regclass('public.store_theme_custom_files') IS NULL THEN RAISE NOTICE 'part 180: store_theme_custom_files is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_custom_files; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF content, path, install_id ON public.store_theme_custom_files FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('file'); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_settings') IS NULL THEN RAISE NOTICE 'part 180: store_theme_settings is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_settings; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF settings, install_id ON public.store_theme_settings FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('settings'); END $do$;
DO $do$ BEGIN IF to_regclass('public.store_theme_pages') IS NULL THEN RAISE NOTICE 'part 180: store_theme_pages is missing, its trigger is skipped.'; RETURN; END IF; DROP TRIGGER IF EXISTS site_live_release_forget ON public.store_theme_pages; CREATE TRIGGER site_live_release_forget AFTER INSERT OR DELETE OR UPDATE OF sections, page_key, install_id ON public.store_theme_pages FOR EACH ROW EXECUTE FUNCTION public.site_live_release_forget('page'); END $do$;
notify pgrst, 'reload schema';
